<?php
/**
 * The Plugins-screen details of one plugin (generated by tools/build/gen-plugin-info.py), run with stand-ins for
 * WordPress. Usage: php tools/validate/plugin-info-test.php <slug> <function prefix> <file relative to the plugin> <main file>
 */
// phpcs:disable -- a command-line test runner with WordPress stubs.
list( , $slug, $p, $rel, $mainfile ) = $argv + array( '', '', '', '', '' );
$root = dirname( __DIR__, 2 ) . "/plugins/$slug";
define( 'ABSPATH', __DIR__ . '/' );
$GLOBALS['hooks'] = array();
function add_filter( $t, $cb ) { $GLOBALS['hooks'][ $t ][] = $cb; }
function add_action( $t, $cb ) { $GLOBALS['hooks'][ $t ][] = $cb; }
function add_thickbox() {}
function plugin_basename( $f ) { return basename( dirname( $f ) ) . '/' . basename( $f ); }
function plugins_url( $p, $f ) { return 'https://example.test/wp-content/plugins/' . basename( dirname( $f ) ) . '/' . $p; }
function menu_page_url( $s, $e ) { return 'https://example.test/wp-admin/admin.php?page=' . $s; }
function admin_url( $p ) { return 'https://example.test/wp-admin/' . $p; }
function esc_url( $u ) { return $u; }
function esc_html( $s ) { return htmlspecialchars( (string) $s ); }
function esc_attr( $s ) { return htmlspecialchars( (string) $s ); }
function esc_html__( $s ) { return htmlspecialchars( $s ); }
function get_plugin_data( $file ) {
	$src = file_get_contents( $file ); $h = array();
	foreach ( array( 'Version' => 'Version', 'RequiresWP' => 'Requires at least', 'RequiresPHP' => 'Requires PHP', 'Description' => 'Description', 'UpdateURI' => 'Update URI' ) as $k => $n ) {
		$h[ $k ] = preg_match( '/^[ \t\/*#@]*' . preg_quote( $n, '/' ) . ':(.*)$/mi', $src, $m ) ? trim( $m[1] ) : '';
	}
	return $h;
}
// the constants a plugin defines before this file loads
define( 'MAIN_FILE', $root . '/' . $mainfile );
foreach ( array( 'KITS_CORE_DIR' => $root . '/', 'DIRECTORYWEB_FILE' => MAIN_FILE, 'RANKWEB_FILE' => MAIN_FILE, 'RANKWEB_DIR' => $root . '/', 'SOURCEWEB_FILE' => MAIN_FILE,
	'INSIGHTWEB_FILE' => MAIN_FILE, 'MAILWEB_FILE' => MAIN_FILE, 'PLANWEB_DIR' => $root . '/' ) as $c => $v ) { define( $c, $v ); }
require "$root/$rel";
$fail = 0;
$ok = function ( $n, $c ) use ( &$fail, $slug ) { if ( ! $c ) { $fail++; echo "FAIL: $slug: $n\n"; } };

$ok( 'the three hooks are added', isset( $hooks['plugins_api'], $hooks['plugin_row_meta'], $hooks['update_plugins_wugweb.com'] ) );
$links = $p . '_row_meta';
$out   = $links( array( 'x' ), plugin_basename( MAIN_FILE ) );
$ok( 'the row gets exactly Getting Started and Documentation', 3 === count( $out ) && false !== strpos( $out[1], 'Getting Started' ) && false !== strpos( $out[2], 'Documentation' ) );
$ok( 'Getting Started opens an admin page', false !== strpos( $out[1], 'admin.php?page=' ) );
$ok( 'Documentation is the product page', false !== strpos( $out[2], "https://wugweb-git.github.io/Kits/plugins/$slug/" ) );
$ok( 'another plugin\'s row is left alone', array( 'x' ) === $links( array( 'x' ), 'other/other.php' ) );

$details = $p . '_details';
$api     = $details( false, 'plugin_information', (object) array( 'slug' => $slug ) );
$ok( 'View details answers for this slug', is_object( $api ) && $slug === $api->slug );
$ok( 'View details ignores another slug', false === $details( false, 'plugin_information', (object) array( 'slug' => 'other' ) ) );
$s = (array) ( $api->sections ?? array() );
foreach ( array( 'description', 'installation', 'faq', 'changelog', 'reviews' ) as $tab ) {
	$ok( "the $tab tab is there and not empty", ! empty( $s[ $tab ] ) );
}
$readme = file_get_contents( "$root/readme.txt" );
$shots  = 0; foreach ( glob( "$root/assets/screenshot-*.png" ) ?: array() as $f ) { $shots++; }
if ( $shots ) {
	$ok( 'the Screenshots tab shows the screenshot files', ! empty( $s['screenshots'] ) && substr_count( $s['screenshots'], '<img' ) <= $shots );
}
$ok( 'the version is the header version', preg_match( '/^[ \t\/*#@]*Version:\s*' . preg_quote( $api->version, '/' ) . '\s*$/mi', file_get_contents( MAIN_FILE ) ) === 1 );
$ok( 'the author is Wugweb', false !== strpos( $api->author, 'Wugweb' ) );
echo $fail ? "$slug plugin-info: $fail failed\n" : "$slug: plugin info ok\n";
exit( $fail ? 1 : 0 );
